  Button Btn(string text,Func<Task> action,bool primary,int width){var b=new Button{Text=text,Width=width,Height=40,FlatStyle=FlatStyle.Flat,BackColor=primary?accent:Color.White,ForeColor=ink,Cursor=Cursors.Hand,Margin=new Padding(0,5,10,5),Font=new Font("Segoe UI",10,FontStyle.Bold)};b.FlatAppearance.BorderColor=Color.FromArgb(212,223,210);b.FlatAppearance.BorderSize=primary?0:1;b.Click+=async delegate{await Use(action);};return b;}
  Button Go(string text,string dest,bool primary,int width){return Btn(text,delegate{ShowPage(dest);return Task.FromResult(0);},primary,width);}
  async Task Use(Func<Task> work){if(busy)return;busy=true;sidebar.Enabled=false;devices.Enabled=false;UseWaitCursor=true;operation.Text="Выполняется…";try{await work();if(!closing)operation.Text="Готово · "+DateTime.Now.ToString("HH:mm");}catch(Exception e){if(!closing){operation.Text="Не выполнено: "+Short(e.Message,140);MessageBox.Show(this,e.Message,"XiaomiDesk",MessageBoxButtons.OK,MessageBoxIcon.Information);}}finally{busy=false;if(!closing){UseWaitCursor=false;sidebar.Enabled=true;devices.Enabled=true;}}}
  void SwitchSerial(string serial){if(adb.Serial==serial)return;ClearGallery();reconnectVersion++;sessionVerified=false;if(stream!=null)stream.Stop();bridge.RotateToken();setupDone=false;setupSerial="";helperSeen=DateTime.MinValue;events.Clear();lastClip="";if(clip!=null&&!clip.IsDisposed)clip.Clear();RefreshNotices();adb.Serial=serial;}
  static string Short(string s,int n){return s==null?"":s.Length>n?s.Substring(0,n)+"…":s;}
  void Need(){if(adb.Serial==null)throw new Exception("Подключите Xiaomi по Wi-Fi или USB в разделе «Подключение» и выберите устройство сверху.");}
  async Task RefreshDevices(){if(refreshing)return;refreshing=true;bool beganBusy=busy;try{var found=Core.ParseDevices(await adb.Run(false,"devices","-l"));if(closing||(busy&&!beganBusy))return;string previous=adb.Serial??((devices.SelectedItem as Device)!=null?((Device)devices.SelectedItem).Serial:null);devices.Items.Clear();foreach(var d in found)devices.Items.Add(d);int selected=found.FindIndex(d=>d.Serial==previous);if(selected<0&&found.Count==1&&string.IsNullOrEmpty(settings.Identity))selected=0;devices.SelectedIndex=selected;var chosen=devices.SelectedItem as Device;SwitchSerial(chosen!=null&&chosen.State=="device"?chosen.Serial:null);if(setupSerial!=adb.Serial)setupDone=false;UpdateState();}catch(Exception e){if(!closing&&!(busy&&!beganBusy)){SwitchSerial(null);state.Text="Нет связи с Android";helper.Text=Short(e.Message,85);}}finally{refreshing=false;}}
  void UpdateState(){var d=devices.SelectedItem as Device;state.Text=adb.Serial!=null?(d!=null?d.Model:"Xiaomi"):d!=null&&d.State=="unauthorized"?"Разрешите подключение на Xiaomi":"Телефон не подключён";helper.Text=adb.Serial!=null?"Подключён · "+(WirelessDiscovery.IsWirelessSerial(adb.Serial)?"Wi-Fi":"USB")+"   /   "+(helperSeen>DateTime.Now.AddSeconds(-20)?"помощник на связи":"помощник ещё не подключён"):"Откройте «Подключение»: Wi-Fi или USB → выбор устройства";if(tray!=null)tray.Text=Short("XiaomiDesk — "+state.Text,63);}
  FlowLayoutPanel Stack(){var p=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(0)};content.Controls.Add(p);return p;}
  Label LabelText(string text,int size,bool bold,int width){return new Label{Text=text,Width=width,AutoSize=false,Height=TextRenderer.MeasureText(text,new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),new Size(width,0),TextFormatFlags.WordBreak).Height+12,ForeColor=bold?ink:muted,Font=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular),Margin=new Padding(0,0,0,12)};}
