  Panel Card(FlowLayoutPanel p,string title,string body){var box=new Panel{Width=820,Height=112,BackColor=Color.White,Padding=new Padding(20),Margin=new Padding(0,0,0,14)};box.Controls.Add(new Label{Text=title,ForeColor=ink,Font=new Font("Segoe UI",13,FontStyle.Bold),Location=new Point(20,16),Size=new Size(770,29)});box.Controls.Add(new Label{Text=body,ForeColor=muted,Location=new Point(20,50),Size=new Size(775,50)});p.Controls.Add(box);return box;}
  void ShowPage(string name){ClearGallery();if(stream!=null){stream.Stop();stream=null;}foreach(Control old in content.Controls.Cast<Control>().ToArray()){content.Controls.Remove(old);old.Dispose();}files=null;path=null;clip=null;notices=null;page=name;foreach(var b in navButtons){bool selected=(string)b.Tag==name;b.BackColor=selected?Color.FromArgb(48,63,94):nav;b.ForeColor=selected?accent:Color.FromArgb(208,222,218);}if(name=="Экран телефона"||name=="Камера"){Media(name=="Камера");return;}var p=Stack();switch(name){case "Обзор":NewOverview(p);break;case "Галерея":Gallery(p);break;case "Ссылки":LinksPage(p);break;case "Инструменты":ToolsPage(p);break;case "Подключение":Connection(p);break;case "Файлы":Files(p);break;case "Передачи":TransfersPage(p);break;case "Настройки":SettingsPage(p);break;case "Уведомления":Notifications(p);break;case "Буфер обмена":ClipboardPage(p);break;case "Звонки и SMS":Calls(p);break;case "Интернет":Internet(p);break;}}
  async Task Install(){Need();string apk=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"phone","XiaomiDesk.apk");string result;try{result=await adb.RunTimeout(true,120000,"install","-r",apk);}catch(IOException e){throw new IOException(Core.InstallFailure(e.Message),e);}if(!result.Contains("Success"))throw new Exception(Core.InstallFailure(result));await Configure();}
  async Task Configure(){Need();await PreparePhoneSession();setupDone=false;await adb.Run(true,"reverse","tcp:"+bridge.Port,"tcp:"+bridge.Port);string output=await adb.Activity("-n app.xiaomidesk/.MainActivity --es token "+Core.ShellQuote(bridge.Token)+" --ei port "+bridge.Port);if(output.Contains("Error"))throw new Exception("Помощник не открылся. Сначала установите его.\n"+output);setupSerial=adb.Serial;setupDone=true;await RememberCurrent(false);}
  async Task HelperAction(string action,string text){Need();if(!setupDone||setupSerial!=adb.Serial){await PreparePhoneSession();await adb.Run(true,"reverse","tcp:"+bridge.Port,"tcp:"+bridge.Port);setupDone=true;setupSerial=adb.Serial;}if(text!=null)bridge.PutClipboard(text);string command="-n app.xiaomidesk/.MainActivity --es token "+Core.ShellQuote(bridge.Token)+" --ei port "+bridge.Port+" --es action "+Core.ShellQuote(action);var result=await adb.Activity(command);if(result.Contains("Error"))throw new Exception(result);}
  async Task LoadFiles(){Need();string requested=Core.PhonePath(path.Text.Trim());var view=files;string result=await adb.Shell("ls -1 -p -- "+Core.ShellQuote(requested));if(view==null||view.IsDisposed)return;remote=requested;path.Text=remote;view.Items.Clear();foreach(var name in result.Replace("\r","").Split('\n').Where(s=>s.Length>0).OrderBy(s=>s.EndsWith("/")?0:1).ThenBy(s=>s)){bool dir=name.EndsWith("/");string clean=dir?name.Substring(0,name.Length-1):name;if(clean=="."||clean=="..")continue;var item=new ListViewItem(clean){Tag=dir};item.SubItems.Add(dir?"Папка":"Файл");view.Items.Add(item);}operation.Text="Элементов: "+view.Items.Count;}
  static string SafeLocalName(string s){foreach(char c in Path.GetInvalidFileNameChars())s=s.Replace(c,'_');return s;}
  void Notifications(FlowLayoutPanel p){Title(p,"Уведомления рядом","Появятся здесь после установки помощника и выдачи доступа на Xiaomi.");var r=Row(p);r.Controls.Add(Btn("Включить на телефоне",async delegate{await HelperAction("notifications",null);},true,245));r.Controls.Add(Btn("Очистить список",delegate{events.Clear();RefreshNotices();return Task.FromResult(0);},false,185));notices=new ListBox{Width=820,Height=360,HorizontalScrollbar=true,BorderStyle=BorderStyle.FixedSingle,Font=new Font("Segoe UI",11),ItemHeight=32};p.Controls.Add(notices);RefreshNotices();Card(p,"Только текущий сеанс","Хранятся последние 150 уведомлений в памяти программы. После закрытия список исчезает. Отключить доступ можно в настройках телефона.");}
  void RefreshNotices(){if(notices==null||notices.IsDisposed)return;notices.Items.Clear();foreach(var e in events)notices.Items.Add((e.title??e.app??"Приложение")+" — "+(e.text??""));}
  void Received(PhoneEvent ev){if(closing||!IsHandleCreated)return;try{BeginInvoke(new Action(delegate{if(closing||!sessionVerified||adb.Serial==null||ev.SessionToken!=bridge.Token)return;helperSeen=DateTime.Now;UpdateState();if(ev.kind=="notification"){events.Insert(0,ev);if(events.Count>150)events.RemoveAt(events.Count-1);RefreshNotices();}if(ev.kind=="clipboard"){lastClip=ev.text??"";if(clip!=null&&!clip.IsDisposed)clip.Text=lastClip;operation.Text="Текст с Xiaomi получен. Нажмите «В буфер Windows», чтобы скопировать.";}}));}catch(InvalidOperationException){}}
  void ClipboardPage(FlowLayoutPanel p){Title(p,"Один текст — два устройства","Передача по кнопке: Android разрешает читать буфер, когда помощник открыт на экране.");clip=new TextBox{Width=820,Height=240,Multiline=true,ScrollBars=ScrollBars.Vertical,MaxLength=16000,Text=lastClip,Font=new Font("Segoe UI",12)};p.Controls.Add(clip);var r=Row(p);r.Controls.Add(Btn("Взять из Windows",delegate{clip.Text=Clipboard.ContainsText()?Clipboard.GetText():"";return Task.FromResult(0);},false,205));r.Controls.Add(Btn("Отправить в Xiaomi",async delegate{if(clip.Text.Length>16000)throw new Exception("Максимум 16 000 символов.");await HelperAction("write",clip.Text);},true,210));r=Row(p);r.Controls.Add(Btn("Получить с Xiaomi",async delegate{await HelperAction("read",null);},false,205));r.Controls.Add(Btn("В буфер Windows",delegate{if(clip.Text.Length>0)Clipboard.SetText(clip.Text);return Task.FromResult(0);},false,210));Card(p,"Подтверждение на Xiaomi","При передаче откроется помощник. Android может показать уведомление о доступе к буферу. Автоматическое фоновое чтение не включается.");}
  void Calls(FlowLayoutPanel p){Title(p,"Звонки и сообщения","Подготовьте номер или SMS здесь и подтвердите действие на телефоне.");p.Controls.Add(LabelText("Номер телефона",11,true,820));var number=new TextBox{Width=420,Font=new Font("Segoe UI",15),Margin=new Padding(0,0,0,14)};p.Controls.Add(number);var r=Row(p);r.Controls.Add(Btn("Открыть набор номера",async delegate{Need();await adb.Activity("-a android.intent.action.DIAL -d "+Core.ShellQuote("tel:"+Core.Number(number.Text)));},true,255));p.Controls.Add(LabelText("Текст SMS",11,true,820));var sms=new TextBox{Width=820,Height=145,Multiline=true,MaxLength=4000,ScrollBars=ScrollBars.Vertical};p.Controls.Add(sms);r=Row(p);r.Controls.Add(Btn("Подготовить SMS",async delegate{Need();await adb.Activity("-a android.intent.action.SENDTO -d "+Core.ShellQuote("smsto:"+Core.Number(number.Text))+" --es sms_body "+Core.ShellQuote(sms.Text.Replace("\r","").Replace("\n"," ")));},false,230));Card(p,"Как проходит звонок","Обычный сотовый звонок и его звук остаются на Xiaomi или подключённой к нему гарнитуре. Передача разговорного звука на ноутбук в этой версии не реализована.");}
  void Internet(FlowLayoutPanel p){Title(p,"Интернет с телефона","Откройте нужные настройки отсюда, затем включите режим модема на Xiaomi.");Card(p,"USB-модем","Оставьте кабель подключённым. На телефоне включите «USB-модем» в разделе точки доступа. Windows должна обнаружить новое сетевое подключение.");Card(p,"Точка доступа Wi-Fi","Включите мобильную точку доступа на Xiaomi, затем подключите ноутбук к её сети. При этом беспроводная отладка может отключиться — используйте USB.");var r=Row(p);r.Controls.Add(Btn("Настройки на Xiaomi",async delegate{Need();string result=await adb.Activity("-a android.settings.TETHER_SETTINGS");if(result.Contains("Error"))await adb.Activity("-a android.settings.WIRELESS_SETTINGS");},true,240));r.Controls.Add(Btn("Сеть в Windows",delegate{Process.Start("ms-settings:network");return Task.FromResult(0);},false,215));p.Controls.Add(LabelText("Программа не включает раздачу скрытно. Финальный переключатель находится в настройках телефона; расходуется мобильный трафик вашего тарифа.",10,false,820));}
